head.script:
scwin.params = new Array();
scwin.vAnufeeNotiImpostNo;
scwin.LD_MKT_TP_CD = js_market;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        getId = $c.frame.path("../").fn_getId;
        scwin.params = getId();
        scwin.vAnufeeNotiImpostNo = scwin.params[3];
        if (scwin.vAnufeeNotiImpostNo !== null) {
            btn_save.hide();
            panel_modify.show("");
        } else {
            btn_save.show("");
            panel_modify.hide();
        }
        await scwin.read();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40802.onpageload" });
    }
};

/**
 * @method
