/**
 * @method
 * @name btn_calculate_onclick
 * @description 「계산」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_calculate_onclick = async function() {
    try {
        const isurCd = txb_SEARCH_ISUR_CD.getValue();
        const deListDD = edt_DelistDD.getValue();
        const deListDecisionDD = edt_DelistDecisionDD.getValue();
        if (isurCd === "") {
            await $c.win.alert('회사를 선택해 주세요');
            return;
        }
        if (deListDecisionDD === "") {
            await $c.win.alert('상장폐지 결정일을 입력해 주세요');
            return;
        }
        if (deListDD === "") {
            await $c.win.alert('상장폐지 전일을 입력해 주세요');
            return;
        }
        if (deListDecisionDD >= deListDD) {
            await $c.win.alert('상장폐지결정일은 상장폐지전일보다\n이전 날짜로 입력해 주세요');
            return;
        }
        let queryId = "";
        if (scwin.LD_MKT_TP_CD === '1') {
            queryId = "lds.stf.lstmgt.yafmgt.yuga.calcuYearAssessmentFeeByDelistDD";
        } else if (scwin.LD_MKT_TP_CD === '2') {
            queryId = "lds.stf.lstmgt.yafmgt.kosdaq.calcuYearAssessmentFeeByDelistDD";
        } else {
            queryId = "lds.stf.lstmgt.yafmgt.yuga.calcuYearAssessmentFeeByDelistDD";
        }
        const sbmOptions = {
            id : "sbm_dts_yearAssessmentFee",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_yearAssessmentFee=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40802.btn_calculate_onclick" });
    }
};

/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
