/**
 * @method
 * @name dts_yearAssessmentFee_OnLoadCompleted
 * @description dts_yearAssessmentFee 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_yearAssessmentFee_OnLoadCompleted = async function(rowcount) {
    try {
        if (rowcount === 0) {
            await $c.win.alert('일평균시가총액이 존재하지 않습니다.');
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40802.dts_yearAssessmentFee_OnLoadCompleted" });
    }
};

/**
 * @method
