///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name read
 * @description read 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    url += "&SCREN_ID=" + "ULDSTF40802.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&ISUR_CD=" + scwin.params[0];
    url += "&BAS_YY=" + scwin.params[1];
    url += "&MKT_ID=" + scwin.params[2];
    url += "&ANULFEE_NOTI_IMPOST_NO=" + scwin.params[3];
    const sbmOptions = {
        id : "sbm_dts_yearAssessmentFee",
        action : "/YearAssessmentFeeManagement.do",
        ref : "",
        target : "dts_yearAssessmentFee=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.setInitialIsurCd();
};

/**
 * @method
 * @name gettNewNotiImpostNo
 * @description gett New Noti Impost No 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gettNewNotiImpostNo = async function() {
    const sbmOptions = {
        id : "sbm_dts_NotiImpostNo",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_NotiImpostNo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    return dts_NotiImpostNo.getCellData(1, "ANULFEE_NOTI_IMPOST_NO");
};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} trsIdx trsIdx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(trsIdx) {
    if (TR_JOB === "I") {
        let vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
        trs_Insert.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Insert",
            action : "/YearAssessmentFeeManagement.do",
            ref : "dts_yearAssessmentFee",
            target : "trs_Insert=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } else if (TR_JOB === "U") {
        let vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
        trs_Update.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Update",
            action : "/YearAssessmentFeeManagement.do",
            ref : "dts_yearAssessmentFee",
            target : "trs_Update=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } else if (TR_JOB === "R") {
        let vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
        trs_Delete.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Delete",
            action : "/YearAssessmentFeeManagement.do",
            ref : "dts_yearAssessmentFee",
            target : "trs_Delete=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setInitialIsurCd
 * @description set Initial Isur Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.setInitialIsurCd = function() {
    txb_SEARCH_ISUR_CD.setValue(dts_yearAssessmentFee.getCellData(1, "ISUR_CD"));
    txb_SEARCH_COM_NM.setValue(dts_yearAssessmentFee.getCellData(1, "COM_NM"));
};

/**
 * @method
 * @name getPar
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = ""; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setPar
 * @description set Par 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setPar = function(arrPar) {
    txb_ZIPCD.setValue(arrPar[0]);
    txb_ADDR.setValue(arrPar[1]);
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[회사]를 선택하세요.");
        txb_SEARCH_ISUR_CD.focus();
        return false;
    }
    if (edt_AVG_MKTCAP.getValue() === "") {
        await $c.win.alert("계산버튼을 클릭하여 [시가총액]을 입력해 주세요.");
        return false;
    }
    if (edt_STKCERT_ANULFEE.getValue() === "") {
        await $c.win.alert("계산버튼을 클릭하여 [수시연부과금액]을 입력해 주세요.");
        return false;
    }
    if (txb_ADDR.getValue() === "") {
        await $c.win.alert("[주소]를 입력해 주세오.");
        txb_ADDR.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    TR_JOB = 'I';
    if (await scwin.checkForm()) {
        scwin.vAnufeeNotiImpostNo = await scwin.gettNewNotiImpostNo();
        dts_yearAssessmentFee.setCellData(1, "ANULFEE_NOTI_IMPOST_NO", scwin.vAnufeeNotiImpostNo);
        dts_yearAssessmentFee.setCellData(1, "LD_MKT_TP_CD", scwin.LD_MKT_TP_CD);
        await scwin.trs(TR_JOB_INSERT);
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    TR_JOB = 'U';
    if (await scwin.checkForm()) {
        let rtn = confirm('내용을 수정 하시겠습니까?');
        if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

        {
            await scwin.trs(TR_JOB_UPDATE);
        }
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    TR_JOB = 'R';
    let rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn === 1) {
        // [확인] 버튼이 눌려졌을 경우
        await scwin.trs(TR_JOB_DELETE);
    }
};
